<?php
require_once __DIR__.'/config.php';
if (!empty($_SESSION['usuario_id'])) { header('Location: perfil.php'); exit; }
$error=''; verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nombre=trim($_POST['nombre']??''); $apellido=trim($_POST['apellido']??''); $correo=trim($_POST['correo']??''); $pass=$_POST['contrasena']??''; $confirm=$_POST['confirmar']??'';
 if($nombre===''||$apellido===''||!filter_var($correo,FILTER_VALIDATE_EMAIL)) $error='Completa tu nombre, apellido y un correo válido.';
 elseif(strlen($pass)<8) $error='La contraseña debe tener al menos 8 caracteres.';
 elseif($pass!==$confirm) $error='Las contraseñas no coinciden.';
 else { try { $conexion->begin_transaction(); $rol='Estudiante'; $estado='Activo'; $q=$conexion->prepare('INSERT INTO usuarios(nombre,apellido,correo,rol,estado) VALUES(?,?,?,?,?)');$q->bind_param('sssss',$nombre,$apellido,$correo,$rol,$estado);$q->execute();$id=(int)$conexion->insert_id;$hash=password_hash($pass,PASSWORD_DEFAULT);$l=$conexion->prepare('INSERT INTO usuarios_login(id_usuario,contrasena_hash) VALUES(?,?)');$l->bind_param('is',$id,$hash);$l->execute();$conexion->commit(); $_SESSION['usuario_id']=$id;$_SESSION['nombre']=$nombre;$_SESSION['apellido']=$apellido;$_SESSION['correo']=$correo;$_SESSION['rol']='Estudiante'; session_regenerate_id(true); header('Location: perfil.php?bienvenida=1');exit; } catch(Throwable $e){$conexion->rollback();$error='No se pudo crear la cuenta. Puede que ese correo ya esté registrado.';} }
}
